function multiSetLive(){multiWorkspaceSeekToken++;multiWorkspaceValue=multiLiveSeconds()??multiWorkspaceValue;multiWorkspaceCameras.forEach((id,index)=>{const video=document.querySelector(`#multi-video-${index}`);if(!video)return;const camera=state.devices.find(device=>device.id===id),label=video.parentElement.querySelector('.multi-camera-tile-label'),missing=video.parentElement.querySelector('.multi-camera-missing');video.dataset.playback='live';video.controls=false;video.removeAttribute('src');video.load();if(camera?.status==='offline'){if(label){label.dataset.state='offline';label.textContent=video.dataset.cameraName}if(missing){missing.hidden=false;missing.textContent='Camera offline'}return}connectLive(video,id);if(label){label.dataset.state='live';label.textContent=video.dataset.cameraName}if(missing)missing.hidden=true});const status=document.querySelector('#workspace-multi-player');if(status)status.textContent='Live view · all cameras are connected independently.';const mode=document.querySelector('#multi-workspace-mode');if(mode){mode.textContent='LIVE';mode.dataset.mode='live'}multiUpdatePlayhead(multiWorkspaceValue)}
function multiTogglePlay(){const videos=[...document.querySelectorAll('.multi-camera-video')],playing=videos.some(video=>!video.paused&&video.dataset.playback==='recording');videos.forEach(video=>{if(video.dataset.playback==='recording')(playing?video.pause():video.play().catch(()=>{}))});const button=document.querySelector('#multi-workspace-play');if(button)button.textContent=playing?'Play':'Pause'}
function multiCloseWorkspace(){multiWorkspaceActive=false;clearInterval(multiWorkspaceTimer);multiWorkspaceSeekToken++;document.querySelectorAll('.multi-camera-video').forEach(video=>{video.pause();video.removeAttribute('src');video.load()});liveWorkspace.hidden=true;hideWorkspacePage();if(history.state?.multi)history.back()}
async function openMultiCameraWorkspace(){const cameras=state.devices.filter(device=>device.kind==='camera').sort((a,b)=>(b.status==='online')-(a.status==='online')).slice(0,4);if(!cameras.length){alert('No cameras are available.');return}multiWorkspaceCameras=cameras.map(camera=>camera.id);multiWorkspaceDate=localDateKey(new Date());multiWorkspaceValue=liveTimelineSeconds()??0;multiWorkspaceActive=true;clearInterval(workspaceTimelineRefreshTimer);history.pushState({multi:true},'',`${location.pathname}#multi-camera`);liveWorkspace.hidden=false;liveWorkspace.classList.add('multi-workspace');liveWorkspace.querySelector('.live-workspace-inner').innerHTML=`<div class="live-workspace-head"><div><h1 id="workspace-title">Camera grid</h1><span id="workspace-subtitle" class="notice">${multiWorkspaceCameras.length} cameras · synchronized live and playback</span></div><div class="workspace-actions"><button class="primary" id="workspace-fullscreen" type="button">Full screen</button></div></div><div class="multi-camera-grid">${cameras.map((camera,index)=>`<article class="multi-camera-tile"><span class="multi-camera-tile-label" data-state="live">${esc(camera.name)}</span><video id="multi-video-${index}" class="multi-camera-video" data-camera-id="${esc(camera.id)}" data-camera-name="${esc(camera.name)}" autoplay muted playsinline></video><span class="multi-camera-missing" hidden></span></article>`).join('')}</div><div class="multi-date-controls"><label>Recording date<input id="multi-workspace-date" type="date" value="${multiWorkspaceDate}"></label></div><div class="multi-playback-controls"><div class="workspace-control-left"><span id="multi-workspace-mode" class="workspace-mode" data-mode="live">LIVE</span><span id="multi-control-time" class="workspace-control-time">${formatTimelineTime(multiWorkspaceValue)}</span></div><div class="workspace-control-center"><button class="ghost" id="multi-back10">−10s</button><button class="primary" id="multi-workspace-play">Pause</button><button class="ghost" id="multi-forward10">+10s</button></div><button class="ghost workspace-return-live" id="multi-return-live">Return to live</button></div><div id="workspace-multi-player" class="workspace-player">Live view · click the shared timeline to play all available recordings together.</div><div id="workspace-multi-timeline"></div>`;showWorkspacePage();const grid=document.querySelector('.multi-camera-grid');for(let empty=cameras.length;empty<4;empty++){const tile=document.createElement('div');tile.className='multi-camera-tile multi-camera-empty';tile.textContent='No camera assigned';grid.appendChild(tile)}document.querySelector('#workspace-fullscreen').onclick=()=>{const grid=document.querySelector('.multi-camera-grid');if(grid?.requestFullscreen)grid.requestFullscreen().catch(()=>{})};document.querySelector('#multi-workspace-play').onclick=multiTogglePlay;document.querySelector('#multi-back10').onclick=()=>multiSeekAll(Math.max(0,multiWorkspaceValue-10));document.querySelector('#multi-forward10').onclick=()=>multiSeekAll(Math.min(multiDaySeconds()-1,multiWorkspaceValue+10));document.querySelector('#multi-return-live').onclick=multiSetLive;document.querySelector('#multi-workspace-date').onchange=async event=>{multiWorkspaceDate=event.target.value;multiWorkspaceValue=0;await multiLoadTimelines();multiSetLive()};document.querySelectorAll('.multi-camera-video').forEach(video=>video.addEventListener('timeupdate',()=>{if(video.dataset.playback==='recording'&&video===document.querySelector('.multi-camera-video')){const records=multiWorkspaceRecords.get(video.dataset.cameraId)||[],record=multiRecordAt(records,multiWorkspaceValue);if(record){multiWorkspaceValue=multiSeconds(record)+video.currentTime;multiUpdatePlayhead(multiWorkspaceValue)}}}));await multiLoadTimelines();multiSetLive();multiWorkspaceTimer=setInterval(()=>{if(multiWorkspaceActive&&document.querySelector('#multi-workspace-mode')?.dataset.mode==='live'){multiWorkspaceValue=liveTimelineSeconds()??multiWorkspaceValue;multiUpdatePlayhead(multiWorkspaceValue)}},1000)}
const closeLiveWorkspaceBeforeMulti=closeLiveWorkspace;closeLiveWorkspace=function(){if(multiWorkspaceActive){multiCloseWorkspace();return}closeLiveWorkspaceBeforeMulti()};window.addEventListener('popstate',()=>{if(multiWorkspaceActive){multiWorkspaceActive=false;clearInterval(multiWorkspaceTimer);document.querySelectorAll('.multi-camera-video').forEach(video=>{video.pause();video.removeAttribute('src');video.load()});liveWorkspace.classList.remove('multi-workspace')}});
const multiSeekAllBeforeMode=multiSeekAll;multiSeekAll=async function(value){const mode=document.querySelector('#multi-workspace-mode');if(mode){mode.textContent='PLAYBACK';mode.dataset.mode='recording'}return multiSeekAllBeforeMode(value)};

/* Commit a scrub without handing control back to the autoplay playback loader. */
const previewWorkspaceTimelineBeforeContinuousScrub=previewWorkspaceTimeline;let workspaceContinuousPreviewValue=null,workspaceContinuousPreviewAt=0;previewWorkspaceTimeline=function(value){const numeric=Number(value)||0,now=performance.now(),elapsed=workspaceContinuousPreviewAt?Math.max(16,now-workspaceContinuousPreviewAt):0,velocity=elapsed&&workspaceContinuousPreviewValue!==null?(numeric-workspaceContinuousPreviewValue)/(elapsed/1000):0;workspaceContinuousPreviewValue=numeric;workspaceContinuousPreviewAt=now;workspaceTimelineLastValue=numeric;cancelAnimationFrame(workspaceTimelineSeekFrame);workspaceTimelineSeekFrame=requestAnimationFrame(()=>updateTimelinePlayhead(numeric));previewWorkspaceTimelineScrub(numeric,velocity)};
scrubWorkspaceTimeline=function(value){const selected=Math.max(0,Math.min(timelineDayLength(workspaceTimelineDate)-1,Number(value)||0)),record=timelineRecordAt(selected),status=document.querySelector('#workspace-player'),video=document.querySelector('#workspace-live');workspaceTimelineLastValue=selected;updateTimelinePlayhead(selected);workspaceSeekToken++;if(!record){stopWorkspaceScrubPreview();if(status)status.innerHTML='<span class="notice">No recording is available at the selected time.</span>';return}const offset=Math.max(0,selected-timelineSeconds(record)),token=workspaceSeekToken;workspaceScrubTimelineValue=selected;workspaceScrubTarget=offset;workspaceScrubLastInputAt=performance.now();workspaceScrubVideo=video;if(video?.dataset.playback==='recording'&&workspacePlaybackUrl===record.url&&video.readyState>=1){video.pause();try{video.currentTime=offset}catch{}updateTimelinePlayhead(selected);return}if(status)status.dataset.seeking='true';loadWorkspaceScrubRecording(record,offset).then(ready=>{if(token!==workspaceSeekToken||!ready)return;video.pause();try{video.currentTime=Math.max(0,workspaceScrubTimelineValue-timelineSeconds(record))}catch{}updateTimelinePlayhead(workspaceScrubTimelineValue);if(status)status.dataset.seeking='false'});}
